class Solution {
public:
    ListNode* deleteDuplicates(ListNode* head) {
        ListNode* dummy = new ListNode(0, head);
        ListNode* prev = dummy;
        while (prev->next) {
            ListNode* cur = prev->next;
            if (cur->next && cur->next->val == cur->val) {
                int v = cur->val;
                while (cur && cur->val == v) cur = cur->next;
                prev->next = cur;
            } else {
                prev = cur;
            }
        }
        return dummy->next;
    }
};
